// Settings -> object (client concierge bot, AI-guarded defaults).
// The Telegram bot secret is no longer read from Settings at all: transport runs entirely through n8n Credentials.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def){ if (v === undefined || v === '') return def; return String(v).toLowerCase() === 'true' || v === '1'; }
function num(v, def){ const n = Number(v); return Number.isFinite(n) ? n : def; }
const cfg = {
  owner_chat_id: settings.owner_chat_id || '<REDACTED_CHAT_ID>',
  timezone: settings.timezone || 'Europe/Chisinau',
  lead_intake_webhook_url: settings.lead_intake_webhook_url || 'https://ghennadi.app.n8n.cloud/webhook/finmentor-lead-intake',
  website_url: settings.website_url || 'https://finmentor.md',
  default_language: (settings.default_language || 'ru').toLowerCase(),
  bot_enabled: bool(settings.bot_enabled, true),
  client_ai_enabled: bool(settings.client_ai_enabled, false),
  client_ai_model: settings.client_ai_model || 'PASTE_AI_MODEL_PLACEHOLDER_HERE',
  client_ai_temperature: num(settings.client_ai_temperature, 0.2)
};
return [{ json: { settings: cfg } }];

// Parse Telegram Update (client bot). Trigger отдаёт update на верхнем уровне (или в .body).
const u = $('Telegram Client Trigger').first().json;
const update = u.body || u;
const cb = update.callback_query || null;
const msg = update.message || update.edited_message || null;

let chat_id='', user_id='', username='', first_name='', last_name='', language='', message_text='', callback_data='', callback_query_id='';
if (cb) {
  chat_id = String(cb.message && cb.message.chat ? cb.message.chat.id : '');
  user_id = String(cb.from ? cb.from.id : '');
  username = (cb.from && cb.from.username) || '';
  first_name = (cb.from && cb.from.first_name) || '';
  last_name = (cb.from && cb.from.last_name) || '';
  language = (cb.from && cb.from.language_code) || '';
  callback_data = cb.data || '';
  callback_query_id = cb.id || '';
} else if (msg) {
  chat_id = String(msg.chat ? msg.chat.id : '');
  user_id = String(msg.from ? msg.from.id : '');
  username = (msg.from && msg.from.username) || '';
  first_name = (msg.from && msg.from.first_name) || '';
  last_name = (msg.from && msg.from.last_name) || '';
  language = (msg.from && msg.from.language_code) || '';
  message_text = msg.text || '';
}
if (!chat_id) return [];  // служебный апдейт без чата — игнор
return [{ json: {
  chat_id, user_id, username, first_name, last_name, language,
  message_text, callback_data, callback_query_id,
  is_callback: !!cb,
  raw_update: JSON.stringify(update).slice(0, 4000)
}}];

// Build Bot Response - FINMENTOR Client Concierge final state-machine.
// State-first rules: when a concrete field is expected, never run intent classification first.
function safeText(value, max = 3800) {
  let text = String(value ?? "")
    .replace(/\r/g, "")
    .replace(/[<>]/g, "")
    .replace(/[_*\[\]()`~>#=|{}]/g, " ")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
  if (!text) text = "Понял. Вернёмся в главное меню, где можно выбрать диагностику, встречу или свободно описать запрос.";
  if (text.length > max) text = text.slice(0, max).trim() + "...";
  return text;
}

function bool(value, fallback = false) {
  if (value === undefined || value === null || value === "") return fallback;
  return String(value).toLowerCase() === "true" || String(value) === "1";
}

function norm(value) {
  return String(value ?? "").toLowerCase().replace(/ё/g, "е").trim();
}

function empty(value) {
  return String(value ?? "").trim() === "";
}

function containsAny(text, patterns) {
  const s = norm(text);
  return patterns.some((pattern) => pattern.test(s));
}

function isNoCompanyText(value) {
  return containsAny(value, [
    /не хочу.*(компан|указывать)/,
    /конфиденциально/,
    /пока не скажу/,
    /позже/,
    /без компании/,
  ]);
}

function isNoContactText(value) {
  return containsAny(value, [
    /не хочу.*(контакт|оставлять)/,
    /без контакта/,
    /пока нет/,
    /позже/,
    /не оставлять/,
  ]);
}

function isNoTurnoverText(value) {
  return containsAny(value, [
    /не хочу.*оборот/,
    /не указывать.*оборот/,
    /без оборота/,
    /оборот.*позже/,
    /конфиденциально/,
  ]);
}

function isConsentYes(value) {
  return containsAny(value, [/^да$/, /соглас/, /подтвержд/, /можно/, /передать/, /\byes\b/, /\bok\b/]);
}

function isConsentNo(value) {
  return containsAny(value, [/^нет$/, /не соглас/, /не надо/, /не передав/, /пока не/, /\bno\b/]);
}

function isPersonIntro(value) {
  const text = safeText(value, 200);
  const s = norm(text);
  if (!s || text.length > 120) return false;
  if (/[?？]/.test(text) || /^(как|что|сколько|когда|где|почему|зачем)\b/.test(s)) return false;
  if (containsAny(s, [/нужен/, /нужна/, /нужно/, /требуется/, /ищу/, /хочу/, /проблем/, /нет/, /стоимост/, /цена/, /услуг/, /помогите/, /консультац/])) return false;
  const words = s
    .replace(/[.,;:!?()[\]{}"«»—–-]/g, " ")
    .split(/\s+/)
    .filter(Boolean);
  if (words.length < 1 || words.length > 5) return false;
  const roleHit = containsAny(s, [
    /собственник/,
    /финансовый директор/,
    /директор/,
    /\bceo\b/,
    /\bcfo\b/,
    /руководитель/,
    /бухгалтер/,
    /управляющ/,
    /основатель/,
  ]);
  const hasLetters = /[a-zа-я]/i.test(text);
  return hasLetters && roleHit;
}

const cfg = (function () {
  try {
    return $("Settings to Object").first().json.settings || {};
  } catch (e) {
    return {};
  }
})();

const site = cfg.website_url || "https://finmentor.md";
const lang = (cfg.default_language || "ru").toLowerCase();
const clientAiEnabled = bool(cfg.client_ai_enabled, false);

const p = $("Parse Telegram Update").first().json;
const chat_id = p.chat_id;
const isCb = !!p.is_callback;
const data = String(p.callback_data || "").trim();
const text = String(p.message_text || "").trim();

const now = new Date().toISOString();

const ALLOWED_STATES = [
  "START",
  "MENU",
  "SERVICE_SELECTED",
  "BUSINESS_MODEL_SELECTED",
  "TURNOVER_SELECTED",
  "MAIN_PAIN_SELECTED",
  "URGENCY_SELECTED",
  "HAS_CFO_SELECTED",
  "DOCUMENTS_SELECTED",
  "CONTACT_NAME_REQUESTED",
  "COMPANY_REQUESTED",
  "CONTACT_REQUESTED",
  "CONSENT_REQUESTED",
  "LEAD_SENT",
  "CONSENT_DECLINED",
  "ENDED",
];

const SERVICE = {
  xray: "Financial X-Ray / диагностика",
  cashflow: "Cash Flow / деньги",
  receivables: "Контроль дебиторской задолженности",
  inventory: "Запасы / оборотный капитал",
  pnl: "P&L / маржинальность",
  bi: "BI / отчётность",
  automation: "Автоматизация",
  cfo: "CFO-сопровождение",
  meeting: "Discovery Call",
  free_text: "Free Text Request",
};

const BUSINESS_MODEL = {
  trade: "Торговля",
  manuf: "Производство",
  construction: "Строительство / Real Estate",
  horeca: "HoReCa",
  services: "Услуги / логистика",
  ecommerce: "E-commerce",
  other: "Другое / смешанная модель",
};

const TURNOVER = {
  lt100: "до 100k EUR/год",
  "100_500": "100k-500k EUR/год",
  "500_2m": "500k-2M EUR/год",
  "2m_10m": "2M-10M EUR/год",
  "10m_plus": "10M+ EUR/год",
  skip: "Не указано",
};

const PAIN = {
  no_money: "Деньги есть в продажах, но не хватает ликвидности",
  no_cashflow: "Нет понятного Cash Flow",
  receivables: "Растёт дебиторская задолженность / деньги зависают у клиентов",
  margin: "Непонятна маржинальность",
  no_profit: "Собственник не видит реальную прибыль",
  manual: "Отчётность собирается вручную",
  no_cfo: "Нет финансового директора / управленческого контроля",
  automation: "Нужна автоматизация финансовой отчётности",
};

const URGENCY = {
  urgent: "Срочно, в течение недели",
  month: "В течение месяца",
  quarter: "В ближайший квартал",
  exploring: "Пока изучаю варианты",
};

const CFO = {
  yes: "Да, есть CFO",
  book_no_control: "Есть бухгалтерия, но нет управленческого контроля",
  none: "Нет отдельного финансового блока",
  unsure: "Сложно оценить",
};

const DOC = {
  cashflow: "Cash Flow / платежи",
  pnl: "P&L / прибыль и убытки",
  receivables: "Дебиторская и кредиторская задолженность",
  sales: "Продажи и маржа",
  excel: "Excel-таблицы",
  nothing: "Пока ничего не подготовлено",
};

function hasContact(s) {
  return !!(s.contact_phone || s.contact_email);
}

function inferState(s) {
  if (!empty(s.contact_name) && empty(s.company)) return "COMPANY_REQUESTED";
  if (!empty(s.contact_name) && !empty(s.company) && !hasContact(s)) return "CONTACT_REQUESTED";
  if (!empty(s.contact_name) && !empty(s.company) && hasContact(s) && empty(s.consent)) return "CONSENT_REQUESTED";
  return s.state || "MENU";
}

function baseSession(seed = {}) {
  return {
    session_id: seed.session_id || "S-" + chat_id + "-" + Date.now(),
    chat_id,
    user_id: seed.user_id || p.user_id || "",
    username: seed.username || p.username || "",
    first_name: seed.first_name || p.first_name || "",
    last_name: seed.last_name || p.last_name || "",
    language: seed.language || p.language || lang,
    state: seed.state || "START",
    created_at: seed.created_at || now,
    updated_at: now,
    last_message_at: now,
    entry_source: seed.entry_source || "telegram_client_concierge",
    selected_service: seed.selected_service || "",
    business_model: seed.business_model || "",
    turnover_range: seed.turnover_range || "",
    main_pain: seed.main_pain || "",
    urgency: seed.urgency || "",
    has_cfo: seed.has_cfo || "",
    documents_status: seed.documents_status || "",
    contact_phone: seed.contact_phone || "",
    contact_email: seed.contact_email || "",
    contact_name: seed.contact_name || "",
    company: seed.company || "",
    free_text_request: seed.free_text_request || "",
    consent: seed.consent || "",
    lead_id: seed.lead_id || "",
    lead_sent_at: seed.lead_sent_at || "",
    status: seed.status || "active",
    notes: seed.notes || "",
    raw_json: seed.raw_json || "",
  };
}

function normalizeSessionRows(rows) {
  const sameChat = rows.filter((r) => String(r.chat_id || "") === String(chat_id));
  const normalized = sameChat.map((r) => baseSession(r));
  normalized.sort((a, b) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0));
  const good = normalized.find((r) => !empty(r.session_id) && !empty(r.state));
  const partial = normalized.find((r) => !empty(r.session_id) || !empty(r.contact_name) || !empty(r.company) || hasContact(r));
  const chosen = good || partial || null;
  if (!chosen) return { session: baseSession(), recovered: false };
  let recovered = false;
  if (!ALLOWED_STATES.includes(chosen.state)) {
    chosen.state = "MENU";
    recovered = true;
  }
  const inferred = inferState(chosen);
  if ((empty(chosen.state) || ["START", "MENU", "SERVICE_SELECTED"].includes(chosen.state)) && inferred !== chosen.state) {
    chosen.state = inferred;
    recovered = true;
  }
  if (empty(chosen.session_id)) {
    chosen.session_id = "S-" + chat_id + "-" + Date.now();
    recovered = true;
  }
  return { session: chosen, recovered };
}

let rawSessions = [];
try {
  rawSessions = $("Get Bot Session").all().map((i) => i.json).filter((r) => r && r.chat_id);
} catch (e) {
  rawSessions = [];
}

let { session, recovered: stateRecovered } = normalizeSessionRows(rawSessions);
session.updated_at = now;
session.last_message_at = now;
if (p.username) session.username = p.username;
if (p.first_name) session.first_name = p.first_name;
if (p.last_name) session.last_name = p.last_name;
if (p.language) session.language = p.language;

const stateBefore = session.state || "START";

function appendNote(flag) {
  const parts = String(session.notes || "").split(";").map((x) => x.trim()).filter(Boolean);
  if (!parts.includes(flag)) parts.push(flag);
  session.notes = parts.join("; ").slice(0, 500);
}

function removeNotes(flags) {
  const remove = new Set(flags);
  const parts = String(session.notes || "").split(";").map((x) => x.trim()).filter(Boolean);
  session.notes = parts.filter((x) => !remove.has(x)).join("; ").slice(0, 500);
}

if (stateRecovered) appendNote("state_recovered");

function kb(rows) {
  return { inline_keyboard: rows };
}

const SITE_BTN = { text: "🌐 Открыть сайт", url: site };
const MENU_ROW = [{ text: "🏠 Главное меню", callback_data: "n|menu" }];

function menuKeyboard() {
  return kb([
    [{ text: "🚀 Короткая диагностика", callback_data: "m|diag" }],
    [{ text: "📅 Запросить встречу", callback_data: "m|meeting_contact" }],
    [{ text: "✍️ Описать запрос своими словами", callback_data: "m|free_text" }],
    [{ text: "💼 Услуги FINMENTOR", callback_data: "m|services" }],
    [SITE_BTN, { text: "❌ Завершить", callback_data: "n|end" }],
  ]);
}

function screenMenu() {
  removeNotes(["awaiting_free_text_request", "contact_flow_active"]);
  session.state = "MENU";
  return {
    state: "MENU",
    text:
      "Здравствуйте. Я FINMENTOR Concierge.\n\n" +
      "Помогу собственнику или руководителю спокойно выбрать первый шаг по финансам — без лишних вопросов и давления.\n\n" +
      "Можно пройти короткую диагностику, запросить встречу или описать задачу своими словами. Как удобнее вам?",
    markup: menuKeyboard(),
    detail: "menu_opened",
  };
}

function screenServices() {
  return {
    state: "MENU",
    text:
      "FINMENTOR помогает собственникам и руководителям навести управленческий финансовый контроль без лишней сложности.\n\n" +
      "Основные направления:\n" +
      "1. Financial X-Ray бизнеса\n" +
      "2. Управленческий Cash Flow и P&L\n" +
      "3. Дебиторская задолженность, запасы и оборотный капитал\n" +
      "4. Power BI dashboards\n" +
      "5. Автоматизация через n8n / Make\n" +
      "6. CFO-as-a-Service\n\n" +
      "Если хотите, можно коротко описать ситуацию или запросить встречу.",
    markup: kb([
      [{ text: "🚀 Короткая диагностика", callback_data: "m|diag" }],
      [{ text: "✍️ Написать запрос", callback_data: "m|free_text" }],
      [{ text: "📅 Запросить встречу", callback_data: "m|meeting_contact" }],
      [SITE_BTN],
      MENU_ROW,
    ]),
    detail: "services_requested",
  };
}

function screenPrice() {
  return {
    state: "MENU",
    text:
      "Стоимость зависит от глубины задачи: Financial X-Ray, Cash Flow/P&L, Power BI, автоматизация или CFO-сопровождение.\n\n" +
      "Чтобы не давать формальную цену без контекста, лучше коротко понять задачу и масштаб.",
    markup: kb([
      [{ text: "📅 Обсудить стоимость на встрече", callback_data: "m|meeting_contact" }],
      [{ text: "🚀 Короткая диагностика", callback_data: "m|diag" }],
      [{ text: "💼 Услуги FINMENTOR", callback_data: "m|services" }],
      MENU_ROW,
    ]),
    detail: "price_question",
  };
}

function screenSkipQuestionnaire() {
  if (empty(session.selected_service)) session.selected_service = SERVICE.free_text;
  return {
    state: "SERVICE_SELECTED",
    text:
      "Понимаю. Тогда не будем проходить диагностику.\n\n" +
      "Можно оставить минимум: имя, компания или сфера, удобный контакт и одна фраза по запросу. Этого достаточно, чтобы эксперт FINMENTOR вернулся к вам предметно.",
    markup: kb([
      [{ text: "✅ Оставить контакт", callback_data: "m|meeting_contact" }],
      [{ text: "✍️ Написать запрос", callback_data: "m|free_text" }],
      [{ text: "💼 Услуги FINMENTOR", callback_data: "m|services" }],
      MENU_ROW,
    ]),
    detail: "questionnaire_skipped",
  };
}

function askFreeText() {
  if (empty(session.selected_service)) session.selected_service = SERVICE.free_text;
  appendNote("awaiting_free_text_request");
  return {
    state: "SERVICE_SELECTED",
    text:
      "Напишите в одном сообщении, что хотите обсудить.\n\n" +
      "Можно коротко: «нет понятного cash flow», «нужен Power BI», «хочу CFO-сопровождение», «нужна встреча».",
    markup: kb([MENU_ROW]),
    detail: "free_text_intent_detected",
  };
}

function askStep(step, prefixText = "") {
  const prefix = prefixText ? prefixText + "\n\n" : "";
  if (step === "service") {
    return {
      state: "SERVICE_SELECTED",
      text: prefix + "Что сейчас важнее всего для вашего бизнеса?",
      markup: kb([
        [{ text: "💰 Cash Flow / деньги", callback_data: "s|cashflow" }],
        [{ text: "📉 Оборотный капитал: задолженность и запасы", callback_data: "s|receivables" }],
        [{ text: "📊 P&L / маржинальность", callback_data: "s|pnl" }],
        [{ text: "📈 BI / отчётность", callback_data: "s|bi" }],
        [{ text: "⚙️ Автоматизация", callback_data: "s|automation" }],
        [{ text: "👤 CFO-сопровождение", callback_data: "s|cfo" }],
        [{ text: "Пока не уверен — нужна диагностика", callback_data: "s|xray" }],
        MENU_ROW,
      ]),
      detail: "start_diagnostic",
    };
  }
  if (step === "business_model") {
    return {
      state: "BUSINESS_MODEL_SELECTED",
      text: prefix + "Какой тип бизнеса ближе всего?",
      markup: kb([
        [{ text: "Торговля", callback_data: "b|trade" }, { text: "Производство", callback_data: "b|manuf" }],
        [{ text: "Строительство / Real Estate", callback_data: "b|construction" }],
        [{ text: "HoReCa", callback_data: "b|horeca" }, { text: "Услуги / логистика", callback_data: "b|services" }],
        [{ text: "E-commerce", callback_data: "b|ecommerce" }, { text: "Другое", callback_data: "b|other" }],
        MENU_ROW,
      ]),
      detail: "business_model_requested",
    };
  }
  if (step === "turnover") {
    return {
      state: "TURNOVER_SELECTED",
      text: prefix + "Ориентировочный оборот компании? Можно не указывать, если сейчас не хотите раскрывать.",
      markup: kb([
        [{ text: "до 100k EUR/год", callback_data: "t|lt100" }],
        [{ text: "100k-500k EUR/год", callback_data: "t|100_500" }],
        [{ text: "500k-2M EUR/год", callback_data: "t|500_2m" }],
        [{ text: "2M-10M EUR/год", callback_data: "t|2m_10m" }],
        [{ text: "10M+ EUR/год", callback_data: "t|10m_plus" }],
        [{ text: "Не хочу указывать", callback_data: "t|skip" }],
        MENU_ROW,
      ]),
      detail: "turnover_requested",
    };
  }
  if (step === "main_pain") {
    return {
      state: "MAIN_PAIN_SELECTED",
      text: prefix + "Что сейчас создаёт самое заметное финансовое напряжение?",
      markup: kb([
        [{ text: "Деньги есть в продажах, но не хватает ликвидности", callback_data: "p|no_money" }],
        [{ text: "Нет понятного Cash Flow", callback_data: "p|no_cashflow" }],
        [{ text: "Растёт дебиторская задолженность", callback_data: "p|receivables" }],
        [{ text: "Не вижу маржу и реальную прибыль", callback_data: "p|no_profit" }],
        [{ text: "Отчёты собираются вручную", callback_data: "p|manual" }],
        [{ text: "Нет финансового директора", callback_data: "p|no_cfo" }],
        MENU_ROW,
      ]),
      detail: "main_pain_requested",
    };
  }
  if (step === "urgency") {
    return {
      state: "URGENCY_SELECTED",
      text: prefix + "Насколько срочно нужно разобраться?",
      markup: kb([
        [{ text: "Срочно, в течение недели", callback_data: "u|urgent" }],
        [{ text: "В течение месяца", callback_data: "u|month" }],
