  if (step === "company") {
    appendNote("contact_flow_active");
    return {
      state: "COMPANY_REQUESTED",
      text:
        prefix +
        "Спасибо. Укажите, пожалуйста, компанию или кратко опишите сферу бизнеса.\n\n" +
        "Например: торговая компания, производство, HoReCa, строительство, услуги, e-commerce.",
